FUNCTION_BLOCK FB
VAR_INPUT
    runRequest      : BOOL;
    pressure        : REAL;
    pressureValid   : BOOL;
    fuelFlow        : REAL;
    steamFlow       : REAL;
    outletCmd       : INT;
    outletFeedback  : INT;
    resetBtn        : BOOL;
END_VAR
VAR_OUTPUT
    tripLatched     : BOOL;
    fuelPermit      : BOOL;
    currentCauseMask: WORD;
    latchedCauseMask: WORD;
    diagnosticActive: BOOL;
END_VAR
VAR
    prevResetBtn    : BOOL := FALSE;
    prevRunRequest  : BOOL := FALSE;
    prevPressureValid: BOOL := FALSE;
    prevPressure    : REAL := 0.0;
    prevOutletCmd   : INT := 0;
    prevOutletFeedback: INT := 0;

    valveStickingCount : INT := 0;
END_VAR

VAR
    risingReset     : BOOL;
    currTripCondition: BOOL;
    tripNow         : BOOL;
    clearTrip       : BOOL;
    tempCauseMask   : WORD;
    valveConditionMet: BOOL;
END_VAR

    risingReset := resetBtn AND NOT prevResetBtn;

    prevResetBtn := resetBtn;

    tempCauseMask := 16#0000;

    IF runRequest THEN
        IF NOT pressureValid THEN
            tempCauseMask := tempCauseMask OR 16#0001;
        END_IF

        valveConditionMet := (outletCmd >= 50) AND (outletFeedback <= 10) AND pressureValid AND (pressure >= 4500.0);

        IF valveConditionMet THEN
            valveStickingCount := valveStickingCount + 1;
        ELSE
            valveStickingCount := 0;
        END_IF

        IF valveStickingCount >= 3 THEN
            tempCauseMask := tempCauseMask OR 16#0002;
        END_IF

        IF (fuelFlow >= 4.0) AND (steamFlow <= 10.0) THEN
            tempCauseMask := tempCauseMask OR 16#0004;
        END_IF

        IF pressureValid AND (pressure >= 4500.0) AND (tempCauseMask = 16#0000) THEN
            tempCauseMask := tempCauseMask OR 16#0008;
        END_IF
    ELSE
        valveStickingCount := 0;
    END_IF

    currentCauseMask := tempCauseMask;

    currTripCondition := (runRequest AND NOT pressureValid) OR (runRequest AND pressureValid AND pressure >= 4500.0);

    tripNow := currTripCondition;

    IF tripNow AND runRequest THEN
        tripLatched := TRUE;
    END_IF

    clearTrip := risingReset AND NOT runRequest AND pressureValid AND (pressure <= 4200.0);

    IF clearTrip THEN
        tripLatched := FALSE;
        latchedCauseMask := 16#0000;
        valveStickingCount := 0;
    END_IF

    IF tripLatched THEN
        latchedCauseMask := latchedCauseMask OR currentCauseMask;
    END_IF

    fuelPermit := runRequest AND NOT tripLatched;

    diagnosticActive := (currentCauseMask <> 16#0000);

    prevRunRequest := runRequest;
    prevPressureValid := pressureValid;
    prevPressure := pressure;
    prevOutletCmd := outletCmd;
    prevOutletFeedback := outletFeedback;

END_FUNCTION_BLOCK
